#include <iostream>
#include <memory>
#include <utility>
#include <new>

class Ejemplo {
public:
    bool hay() const { return dato_ != nullptr; }
    int etiqueta() const { return etiqueta_; }
    bool coherente() const {
        return dato_ ? etiqueta_ >= 1 && etiqueta_ <= 9 : etiqueta_ == 0;
    }
private:
    std::unique_ptr<int> dato_ = std::make_unique<int>(4);
    int etiqueta_ = 3;
};

int main() {
    Ejemplo origen;
    Ejemplo destino{std::move(origen)};

    std::cout << origen.hay() << ':' << origen.etiqueta() << ':'
              << origen.coherente() << '|' << destino.hay() << ':'
              << destino.etiqueta() << ':' << destino.coherente();
    return 0;
}

#include <iostream>
#include <memory>
#include <utility>
#include <new>

class Muestra {
public:
    Muestra() = default;
    Muestra(const Muestra&) = delete;
    Muestra& operator=(const Muestra&) = delete;
    Muestra(Muestra&& otra);
    Muestra& operator=(Muestra&& otra);
    ~Muestra() = default;
    bool hay() const { return dato_ != nullptr; }
    int valor() const { return *dato_; }
    int etiqueta() const { return etiqueta_; }
    const int* acceso() const { return dato_.get(); }
    bool coherente() const {
        return dato_ ? etiqueta_ >= 1 && etiqueta_ <= 9 : etiqueta_ == 0;
    }

    bool poner(int valor, int etiqueta);
    bool cambiar(int valor);
    bool reetiquetar(int etiqueta);
    bool vaciar();
private:
    std::unique_ptr<int> dato_{};
    int etiqueta_ = 0;
};

bool Muestra::poner(int valor, int etiqueta) {
    if (valor < 0 || valor > 9 || etiqueta < 1 || etiqueta > 9) {
        return false;
    }
    try {
        auto candidato = std::make_unique<int>(valor);
        dato_.swap(candidato);
        etiqueta_ = etiqueta;
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Muestra::cambiar(int valor) {
    if (!dato_ || valor < 0 || valor > 9) {
        return false;
    }
    *dato_ = valor;
    return true;
}

bool Muestra::reetiquetar(int etiqueta) {
    if (!dato_ || etiqueta < 1 || etiqueta > 9) {
        return false;
    }
    etiqueta_ = etiqueta;
    return true;
}

bool Muestra::vaciar() {
    dato_.reset();
    etiqueta_ = 0;
    return true;
}

int main() {
    Muestra origen;
    if (!origen.poner(4, 1)) { return 1; }
    Muestra&& acceso = std::move(origen);
    std::cout << origen.hay() << ':' << origen.valor() << ':'
              << origen.etiqueta() << ':' << (&acceso == &origen);
    return 0;
}

