bool indice_valido(int indice) {
    return indice == 0 || indice == 1;
}

bool transferir(Muestra& origen, Muestra& destino) {
    if (&origen == &destino) {
        destino = std::move(origen);
        return true;
    }
    Muestra intermedia{std::move(origen)};
    destino = std::move(intermedia);
    return true;
}

void mostrar_dato(bool hay, int valor, int etiqueta) {
    if (hay) {
        std::cout << valor;
    } else {
        std::cout << 'X';
    }
    std::cout << '/' << etiqueta;
}

