    std::cout << "Inicio:";
    mostrar(primera, segunda);
    std::cout << '\n';
    for (int i = 0; i < cantidad; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;
        int c = 0;

        if (!(std::cin >> operacion >> a >> b >> c)) {
            return 1;
        }
        const bool habia0 = primera.hay();
        const bool habia1 = segunda.hay();
        const int anterior0 = habia0 ? primera.valor() : 0;
        const int anterior1 = habia1 ? segunda.valor() : 0;
        const int etiqueta0 = primera.etiqueta();
        const int etiqueta1 = segunda.etiqueta();
        bool aceptado = false;

        if (operacion == 1 && indice_valido(a) && indice_valido(b)) {
            Muestra& origen = a == 0 ? primera : segunda;
            Muestra& destino = b == 0 ? primera : segunda;
            aceptado = transferir(origen, destino);
        } else if (indice_valido(a)) {
            Muestra& muestra = a == 0 ? primera : segunda;
            if (operacion == 2) {
                aceptado = muestra.poner(b, c);
            } else if (operacion == 3) {
                aceptado = muestra.vaciar();
            } else if (operacion == 4) {
                aceptado = muestra.cambiar(b);
            } else if (operacion == 5) {
                aceptado = muestra.reetiquetar(b);
            }
        }
        std::cout << "Resultado:" << aceptado << ";Antes:";
        mostrar_dato(habia0, anterior0, etiqueta0);
        std::cout << ':';
        mostrar_dato(habia1, anterior1, etiqueta1);
        std::cout << ";Actual:";
        mostrar(primera, segunda);
        std::cout << '\n';
    }
    std::cout << "Final:";
    mostrar(primera, segunda);
    std::cout << ";Coherentes:" << primera.coherente() << ':'
              << segunda.coherente();
    return 0;
}

